import Foundation
import XCTest

/// Loads ios/Tests/Fixtures/*.json — the verbatim stdout of the real server
/// commands, regenerated by `python3 server/tests/export_fixtures.py` and kept
/// honest by `bash server/tests/run_all.sh` (which re-exports and fails on any
/// drift). Tests decode THESE bytes, never a hand-written approximation.
enum Fixture {

    static func data(_ name: String, file: StaticString = #filePath, line: UInt = #line) throws -> Data {
        let bundle = Bundle(for: BundleToken.self)
        guard let url = bundle.url(forResource: name, withExtension: "json") else {
            XCTFail("fixture \(name).json is missing from the test bundle — "
                    + "re-run: python3 server/tests/export_fixtures.py", file: file, line: line)
            throw CocoaError(.fileNoSuchFile)
        }
        return try Data(contentsOf: url)
    }

    /// The fixture text exactly as the server printed it (used where a test wants
    /// to feed the raw stdout to the same decode path the app uses).
    static func text(_ name: String, file: StaticString = #filePath, line: UInt = #line) throws -> String {
        String(decoding: try data(name, file: file, line: line), as: UTF8.self)
    }

    static func decode<T: Decodable>(_ type: T.Type, _ name: String,
                                     file: StaticString = #filePath, line: UInt = #line) throws -> T {
        try JSONDecoder().decode(type, from: try data(name, file: file, line: line))
    }

    /// The fixture as a mutable JSON tree, for the tolerance cases (drop a field,
    /// add an unknown one, corrupt one row) — so the malformed input is DERIVED
    /// from real server output instead of invented.
    static func json(_ name: String, file: StaticString = #filePath, line: UInt = #line) throws -> Any {
        try JSONSerialization.jsonObject(with: try data(name, file: file, line: line))
    }

    static func rows(_ name: String, file: StaticString = #filePath, line: UInt = #line) throws -> [[String: Any]] {
        (try json(name, file: file, line: line) as? [[String: Any]]) ?? []
    }

    static func object(_ name: String, file: StaticString = #filePath, line: UInt = #line) throws -> [String: Any] {
        (try json(name, file: file, line: line) as? [String: Any]) ?? [:]
    }

    /// Re-serialize an edited fixture tree back to bytes.
    static func bytes(_ value: Any) throws -> Data {
        try JSONSerialization.data(withJSONObject: value)
    }

    private final class BundleToken {}
}
